"""Audit the two live pfSense firewalls against the configuration generated from the inventory (PLAN_02 FW.1).

  python automation/fw_audit.py        -> report/evidence/fw_audit.txt, exit code 1 when a difference is found

For FW-A and FW-B, over SSH from ADMIN-WS:
  * the running config.xml is compared, section by section, with configs/pfsense/<FW>.config.xml (generated by
    gen_pfsense.py; volatile stamps ignored);
  * every generated filter rule must be loaded in pf (its description is its pf label), and nothing else;
  * the NAT rules, the CARP roles and the absence of the first-time setup wizard are checked.
Nothing is changed on the firewalls.
"""
import datetime
import html
import re
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from adminws import ssh_batch  # noqa: E402

NET = Path(__file__).resolve().parents[1]
FW = {"FW-A": ("fw-a", "MASTER"), "FW-B": ("fw-b", "BACKUP")}
SECTIONS = ["interfaces", "vlans", "laggs", "virtualip", "gateways", "staticroutes", "aliases", "nat", "filter", "hasync",
            "syslog", "snmpd"]
VOLATILE = {"created", "updated", "time", "username"}       # stamps written by pfSense or by the generator
COMMANDS = ["cat /cf/conf/config.xml", "pfctl -sr", "pfctl -sn", "ifconfig | grep carp:",
            "ls /cf/conf/trigger_initial_wizard 2>/dev/null | wc -l"]


def canon(node):
    if node is None:
        return "<absent>"
    kids = [canon(k) for k in node if k.tag not in VOLATILE]
    # pfSense stores descriptions with HTML entities (&gt;, &eacute;): compare the decoded text
    return f"<{node.tag}>{html.unescape((node.text or '').strip())}{''.join(kids)}</{node.tag}>"


def descrs(root, section):
    sec = root.find(section)
    return [html.unescape(r.findtext("descr") or "") for r in (sec.findall("rule") if sec is not None else [])]


def audit(name, alias, role, res, log):
    diffs = 0
    (rc_cfg, cfg), (_, rules), (_, nat), (_, carp), (_, wizard) = res

    def check(ok, text):
        nonlocal diffs
        diffs += not ok
        log(f"  [{'ok' if ok else 'DIFF'}] {text}")

    log(f"== {name} ({alias})")
    if rc_cfg != 0 or "<pfsense>" not in cfg:
        check(False, "could not read /cf/conf/config.xml over SSH")
        return diffs
    live = ET.fromstring(cfg[cfg.index("<?xml"):] if "<?xml" in cfg else cfg)
    gen = ET.parse(NET / "configs" / "pfsense" / f"{name}.config.xml").getroot()
    for sec in SECTIONS:
        same = canon(live.find(sec)) == canon(gen.find(sec))
        detail = ""
        if not same and sec in ("filter", "nat"):
            lv, gn = descrs(live, sec), descrs(gen, sec)
            miss = [d for d in gn if d not in lv]
            extra = [d for d in lv if d not in gn]
            detail = f": {len(lv)} live / {len(gn)} generated rules" + "".join(f"\n         missing live: {d}" for d in miss) \
                     + "".join(f"\n         only live:    {d}" for d in extra)
            if not miss and not extra:
                detail += " (same rules, different attributes or order)"
        check(same, f"config section <{sec}> identical to the generated file{detail}")
    cut = lambda d: d.encode()[:40]                     # pf truncates a label to 63 bytes: compare on a common prefix
    labels = {cut(d) for d in re.findall(r'label "USER_RULE: ([^"]*)"', rules)}
    wanted = {cut(d) for d in descrs(gen, "filter") if d}
    for d in sorted(wanted - labels):
        check(False, f"generated rule not loaded in pf: {d.decode(errors='replace')}...")
    for d in sorted(labels - wanted - {cut(x) for x in descrs(gen, "nat")}):
        check(False, f"rule loaded in pf but not generated: {d.decode(errors='replace')}...")
    check(not (wanted - labels), f"{len(wanted & labels)}/{len(wanted)} generated rule descriptions loaded in pf ({rules.count(chr(10)) + 1} pf lines)")
    check("192.0.2.10" in nat, "outbound NAT to 192.0.2.10 loaded")
    check(len(re.findall(r"rdr .*192\.0\.2\.80", nat)) >= 2, "port forwards of 192.0.2.80 (80, 443) loaded")
    states = re.findall(r"carp: (\w+) vhid", carp)
    check(len(states) == 5 and set(states) == {role}, f"CARP: {len(states)} virtual addresses, state {sorted(set(states))} (expected 5 x {role})")
    check(wizard.strip() == "0", "first-time setup wizard trigger absent")
    timeout = live.find("system/webgui/session_timeout")
    log(f"  [info] web session timeout: {timeout.text + ' min' if timeout is not None else 'not set (pfSense default, 240 min)'}")
    return diffs


def main():
    lines = [f"# Firewall audit - live pfSense against the generated configuration - {datetime.datetime.now():%Y-%m-%d %H:%M}"]

    def log(text):
        print(text)
        lines.append(text)

    res = ssh_batch([(alias, cmd) for alias, _ in FW.values() for cmd in COMMANDS], timeout=45)
    total = 0
    for i, (name, (alias, role)) in enumerate(FW.items()):
        total += audit(name, alias, role, res[i * len(COMMANDS):(i + 1) * len(COMMANDS)], log)
    log(f"\n{total} difference(s)")
    (NET / "report" / "evidence" / "fw_audit.txt").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
    return 1 if total else 0


if __name__ == "__main__":
    sys.exit(main())
